-- Newsletter DRAFTS generated by scripts/newsletter-drafts/build.mts.
-- Inserts as status 'draft' / stage 'early'; nothing here schedules or sends.
-- Skips any draft whose title already exists. Safe to re-run.

-- signal-illustrations-1
insert into public.newsletters
  (title, subject, preheader, audience, blocks, status, stage)
select
  'Signal illustrations 1: Beth, Jacob and Kelvin',
  '🖍️ Signal, as it was drawn live',
  'Before the talk videos are released, see Beth, Jacob and Kelvin''s talks sketched in real time.',
  'subscribers',
  $nl$[{"id":"signal-illustrations-1-01","type":"image","src":"https://tedxnewy.com.au/images/newsletter/alex-desk-tedx.jpg","alt":"Alex Wegner's graphic recording desk at TEDxNewy Signal, covered in red and black marker artwork","widthPct":"full"},{"id":"signal-illustrations-1-02","type":"header","text":"Signal, as it was drawn live.","size":"lg"},{"id":"signal-illustrations-1-03","type":"text","html":"<p>Before talk videos from Signal are released, we wanted to share something a little different: the talks as they were drawn live on the day.</p><p>Over the next week we'll send you the illustrations from each session.</p>"},{"id":"signal-illustrations-1-04","type":"divider","style":"short","colour":"soft"},{"id":"signal-illustrations-1-05","type":"columns","cols":[[{"id":"signal-illustrations-1-06","kind":"image","src":"https://tedxnewy.com.au/images/newsletter/alex-portrait.jpg","alt":"Alex Wegner drawing on a tablet during Signal","widthPct":100}],[{"id":"signal-illustrations-1-07","kind":"text","html":"<p>Every one of these illustrations was created live at the event by our Official Graphic Recorder for TEDxNewy 2026: <strong>Alex Wegner of Sketch it Live</strong>.</p><p>Alex brought her talents to TEDxNewy for the first time this year. Her work means you can get a real feel for what each talk explored before the videos are released.</p>"}]],"ratio":"40-60","valign":"middle"},{"id":"signal-illustrations-1-08","type":"text","html":"<p>Alex founded <a href=\"https://sketchitlive.com.au\">Sketch it Live</a> in 2017, drawing on more than 20 years as a graphic designer, illustrator and UX designer in London, Sydney, Melbourne and Canberra. Her idea is simple: visual language is universal, and it makes information easier to take in and more engaging.</p>"},{"id":"signal-illustrations-1-09","type":"divider","style":"short","colour":"soft"},{"id":"signal-illustrations-1-10","type":"header","text":"The first three talks","size":"md"},{"id":"signal-illustrations-1-11","type":"image","src":"https://tedxnewy.com.au/images/newsletter/illustration-beth.jpg","alt":"Live illustration of Beth Gwalter's talk: regret and grief, the unlived life, sliding doors","widthPct":"full","href":"https://tedxnewy.com.au/images/newsletter/illustration-beth.jpg"},{"id":"signal-illustrations-1-12","type":"text","html":"<p><strong>Beth Gwalter</strong> on grieving and mourning the decisions we didn't make.</p>"},{"id":"signal-illustrations-1-13","type":"image","src":"https://tedxnewy.com.au/images/newsletter/illustration-jacob.jpg","alt":"Live illustration of Jacob Ure's talk: place, short form video and bringing history into community","widthPct":"full","href":"https://tedxnewy.com.au/images/newsletter/illustration-jacob.jpg"},{"id":"signal-illustrations-1-14","type":"text","html":"<p><strong>Jacob Ure</strong> on digital storytelling and bringing history into community.</p>"},{"id":"signal-illustrations-1-15","type":"image","src":"https://tedxnewy.com.au/images/newsletter/illustration-kelvin.jpg","alt":"Live illustration of Professor Kelvin Kong's talk: hearing loss, muku and the sound of silence","widthPct":"full","href":"https://tedxnewy.com.au/images/newsletter/illustration-kelvin.jpg"},{"id":"signal-illustrations-1-16","type":"text","html":"<p><strong>Professor Kelvin Kong AM</strong> on otitis media, culture and healthcare equity.</p>"},{"id":"signal-illustrations-1-17","type":"button","label":"Click to view illustrations here","href":"https://tedxnewy.com.au/images/newsletter/illustration-beth.jpg","align":"center","theme":"red","variant":"solid"},{"id":"signal-illustrations-1-18","type":"divider","style":"short","colour":"soft"},{"id":"signal-illustrations-1-19","type":"text","html":"<p>Keep an eye out for the next set later this week.</p><p>~TEDxNewy Team</p>"}]$nl$::jsonb,
  'draft',
  'early'
where not exists (
  select 1 from public.newsletters where title = 'Signal illustrations 1: Beth, Jacob and Kelvin'
);

-- signal-illustrations-2
insert into public.newsletters
  (title, subject, preheader, audience, blocks, status, stage)
select
  'Signal illustrations 2: William and Chloe',
  '🔴 Set two: our student speakers, drawn live',
  'William Krause and Chloe McGovern, captured in real time with no chance to redo it.',
  'subscribers',
  $nl$[{"id":"signal-illustrations-2-01","type":"image","src":"https://tedxnewy.com.au/images/newsletter/illustration-william.jpg","alt":"Live illustration of William Krause's talk: virtue signalling, from doing good to looking good","widthPct":"full","href":"https://tedxnewy.com.au/images/newsletter/illustration-william.jpg"},{"id":"signal-illustrations-2-02","type":"header","text":"Our student speakers, drawn live.","size":"lg"},{"id":"signal-illustrations-2-03","type":"text","html":"<p>We know you've been eagerly waiting for the second set of live illustrations from the weekend, and this email contains our amazing and unreal student speakers!</p>"},{"id":"signal-illustrations-2-04","type":"header","text":"William Krause","size":"md"},{"id":"signal-illustrations-2-05","type":"text","html":"<p>On virtue signalling.</p>"},{"id":"signal-illustrations-2-06","type":"image","src":"https://tedxnewy.com.au/images/newsletter/illustration-chloe.jpg","alt":"Live illustration of Chloe McGovern's talk: shame should be for the perpetrators","widthPct":"full","href":"https://tedxnewy.com.au/images/newsletter/illustration-chloe.jpg"},{"id":"signal-illustrations-2-07","type":"header","text":"Chloe McGovern","size":"md"},{"id":"signal-illustrations-2-08","type":"text","html":"<p>On how we speak about sexual assault with young people.</p>"},{"id":"signal-illustrations-2-09","type":"button","label":"Click to view illustrations here","href":"https://tedxnewy.com.au/images/newsletter/illustration-william.jpg","align":"center","theme":"red","variant":"solid"},{"id":"signal-illustrations-2-10","type":"divider","style":"short","colour":"soft"},{"id":"signal-illustrations-2-11","type":"header","text":"Drawing a talk while it's being spoken","size":"md"},{"id":"signal-illustrations-2-12","type":"text","html":"<p>Capturing a talk as a drawing while it's being spoken is a real skill. It means listening closely, deciding what matters, and turning ideas into images in real time, with no chance to redo it.</p><p>That's the work of our Official Graphic Recorder for TEDxNewy 2026: <strong>Alex Wegner of Sketch it Live</strong>. Since 2017 she has sketched, animated, illustrated and graphic recorded for businesses, government departments and not-for-profits, in meetings, strategic workshops, conferences and festivals.</p><p>We're grateful she brought that to our student speakers, and gave her time in-kind to do it.</p>"},{"id":"signal-illustrations-2-13","type":"button","label":"Check out more of Alex's work here","href":"https://sketchitlive.com.au","align":"center","theme":"ink","variant":"outline"},{"id":"signal-illustrations-2-14","type":"divider","style":"short","colour":"soft"},{"id":"signal-illustrations-2-15","type":"text","html":"<p>More to come, with our final two talks coming soon.</p><p>~TEDxNewy Team</p>"}]$nl$::jsonb,
  'draft',
  'early'
where not exists (
  select 1 from public.newsletters where title = 'Signal illustrations 2: William and Chloe'
);

-- signal-illustrations-3
insert into public.newsletters
  (title, subject, preheader, audience, blocks, status, stage)
select
  'Signal illustrations 3: Melissa and Sam',
  '❤️ The final two, drawn live (and a thank you)',
  'Melissa Histon and Sam Watson closed Signal. Here''s how Alex drew them.',
  'subscribers',
  $nl$[{"id":"signal-illustrations-3-01","type":"image","src":"https://tedxnewy.com.au/images/newsletter/illustration-mel.jpg","alt":"Live illustration of Melissa Histon's talk: who are you ready to become next?","widthPct":"full","href":"https://tedxnewy.com.au/images/newsletter/illustration-mel.jpg"},{"id":"signal-illustrations-3-02","type":"header","text":"The talks that closed the day.","size":"lg"},{"id":"signal-illustrations-3-03","type":"text","html":"<p>This is the last set of illustrations from the weekend, and it's of the two talks that closed the day.</p>"},{"id":"signal-illustrations-3-04","type":"header","text":"Melissa Histon","size":"md"},{"id":"signal-illustrations-3-05","type":"text","html":"<p>On seeing our past as research for where we are today.</p>"},{"id":"signal-illustrations-3-06","type":"image","src":"https://tedxnewy.com.au/images/newsletter/illustration-sam.jpg","alt":"Live illustration of Sam Watson's talk: where is your motivation pointing?","widthPct":"full","href":"https://tedxnewy.com.au/images/newsletter/illustration-sam.jpg"},{"id":"signal-illustrations-3-07","type":"header","text":"Sam Watson","size":"md"},{"id":"signal-illustrations-3-08","type":"text","html":"<p>Who closed us with motivation, asking: where is it pointing?</p>"},{"id":"signal-illustrations-3-09","type":"button","label":"Click to view illustrations here","href":"https://tedxnewy.com.au/images/newsletter/illustration-mel.jpg","align":"center","theme":"red","variant":"solid"},{"id":"signal-illustrations-3-10","type":"divider","style":"short","colour":"soft"},{"id":"signal-illustrations-3-11","type":"header","text":"Thank you, Alex","size":"md"},{"id":"signal-illustrations-3-12","type":"image","src":"https://tedxnewy.com.au/images/newsletter/alex-crowd.jpg","alt":"Alex Wegner chatting with guests in the foyer at TEDxNewy Signal","widthPct":100},{"id":"signal-illustrations-3-13","type":"text","html":"<p>Across three emails, you've now seen every talk through Alex Wegner's eyes. We'd like to finish by saying a proper thank you.</p><p>Through her illustrations, Alex gave our audience, and now you, a way to take the ideas home before the videos are out. That's a real contribution to our event and something we are incredibly grateful for.</p>"},{"id":"signal-illustrations-3-14","type":"divider","style":"short","colour":"soft"},{"id":"signal-illustrations-3-15","type":"header","text":"Work with Sketch it Live","size":"md"},{"id":"signal-illustrations-3-16","type":"text","html":"<p>If you've been moved by her work, there's a good chance your own team, event or organisation could benefit from it too.</p><p>Sketch it Live works with small and large businesses, government departments, local government, not-for-profits, universities, schools, and event organisers, producing one-of-a-kind visual artefacts through illustration, graphic recording and animation.</p><p>You can find Alex's website here to get in touch.</p>"},{"id":"signal-illustrations-3-17","type":"button","label":"Alex's website","href":"https://sketchitlive.com.au","align":"center","theme":"ink","variant":"outline"},{"id":"signal-illustrations-3-18","type":"divider","style":"short","colour":"soft"},{"id":"signal-illustrations-3-19","type":"text","html":"<p>Thank you, Alex.</p><p>~TEDxNewy Team</p>"}]$nl$::jsonb,
  'draft',
  'early'
where not exists (
  select 1 from public.newsletters where title = 'Signal illustrations 3: Melissa and Sam'
);

-- signal-thank-you-whats-next
insert into public.newsletters
  (title, subject, preheader, audience, blocks, status, stage)
select
  'Signal: thank you and what''s next',
  'You were the signal ❤️ Thank you, Newy',
  'Thank you for Signal. Keep an eye on your inbox this week: we''ve got something good coming.',
  'subscribers',
  $nl$[{"id":"signal-thank-you-whats-next-01","type":"image","src":"https://tedxnewy.com.au/images/newsletter/signal-hero.jpg","alt":"A packed audience at a TEDxNewy event","widthPct":"full"},{"id":"signal-thank-you-whats-next-02","type":"header","text":"You were the signal.","size":"lg"},{"id":"signal-thank-you-whats-next-03","type":"text","html":"<p>Thank you for being part of Signal on Saturday.</p><p>A room full of Novocastrians came together to share ideas, and that only works because people show up. You did.</p><p>We're still catching our breath, and we're very grateful.</p>"},{"id":"signal-thank-you-whats-next-04","type":"divider","style":"short","colour":"soft"},{"id":"signal-thank-you-whats-next-05","type":"header","text":"Thank you to our partners","size":"md"},{"id":"signal-thank-you-whats-next-06","type":"image","src":"https://tedxnewy.com.au/images/newsletter/partners-lockup.jpg","alt":"Our partners: University of Newcastle, Henderson, Hey Zomi, Frekl, Newy Digital and Sketch It Live","widthPct":100,"href":"https://tedxnewy.com.au/sponsors"},{"id":"signal-thank-you-whats-next-07","type":"text","html":"<p>TEDxNewy is volunteer-run, and days like Saturday happen because local businesses and organisations back us.</p><p>Thank you to the <a href=\"https://www.newcastle.edu.au\">University of Newcastle</a>, <a href=\"https://henderson.com.au\">Henderson</a>, <a href=\"https://www.heyzomi.com\">Hey Zomi</a>, <a href=\"https://www.frekl.com.au\">Frekl</a> and <a href=\"https://www.newydigital.com\">Newy Digital</a>.</p><p>And to <a href=\"https://sketchitlive.com.au\">Sketch it Live</a>, whose Alex Wegner drew every talk live on the day. You'll be seeing a lot of her work this week.</p><p>If you're looking for someone to work with, please consider backing the people who backed us.</p>"},{"id":"signal-thank-you-whats-next-08","type":"button","label":"Meet our partners","href":"https://tedxnewy.com.au/sponsors","align":"center","theme":"ink","variant":"outline"},{"id":"signal-thank-you-whats-next-09","type":"divider","style":"short","colour":"soft"},{"id":"signal-thank-you-whats-next-10","type":"header","text":"Keep an eye on your inbox","size":"md"},{"id":"signal-thank-you-whats-next-11","type":"text","html":"<p>Over the coming days we'll be sharing content from event day, a little at a time.</p><p>First up: the talks as they were drawn live on the day, before the videos are released.</p><p>Watch closely. We'd hate for you to miss it.</p>"},{"id":"signal-thank-you-whats-next-12","type":"divider","style":"short","colour":"soft"},{"id":"signal-thank-you-whats-next-13","type":"header","text":"Want to be part of what's next?","size":"md"},{"id":"signal-thank-you-whats-next-14","type":"text","html":"<p>Saturday didn't happen by itself. A crew of volunteers made it happen.</p><p>If you spent the day thinking <em>I could help with that</em>, we'd love to hear from you. No pressure. (Okay, a tiny bit of pressure.)</p>"},{"id":"signal-thank-you-whats-next-15","type":"button","label":"Volunteer with us","href":"https://tedxnewy.com.au/volunteer","align":"center","theme":"red","variant":"solid"},{"id":"signal-thank-you-whats-next-16","type":"text","html":"<p>Thank you again.</p><p>Will and the TEDxNewy team</p>"}]$nl$::jsonb,
  'draft',
  'early'
where not exists (
  select 1 from public.newsletters where title = 'Signal: thank you and what''s next'
);
